package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.jlinalg.omics.methylation.AllcoolsPosterior;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Expected values are generated by the original pinned Python functions, not Java. */
class AllcoolsPosteriorReferenceTest {
    private static double numeric(String s){return switch(s){case "NaN"->Double.NaN;case "Inf"->Double.POSITIVE_INFINITY;case "-Inf"->Double.NEGATIVE_INFINITY;default->Double.parseDouble(s);};}
    private static double[] doubles(String s){return Arrays.stream(s.split(",",-1)).mapToDouble(AllcoolsPosteriorReferenceTest::numeric).toArray();}
    private static long[] integers(String s){return Arrays.stream(s.split(",",-1)).mapToLong(Long::parseLong).toArray();}
    private static boolean agrees(double expected,double actual){return Double.isNaN(expected)?Double.isNaN(actual):Double.isInfinite(expected)?expected==actual:Double.isFinite(actual)&&Math.abs(expected-actual)<=1e-11+Math.abs(expected)*1e-11;}
    @Test void originalAllcoolsFunctionsAgreeAcrossEverySyntheticCase()throws Exception {
        long compared=0,failed=0;int cases=0,refused=0;var failures=new ArrayList<String>();var policy=new HashSet<String>();
        try(var raw=Objects.requireNonNull(getClass().getResourceAsStream("/org/jlinalg/omics/allcools-posterior/REFUSALS.json"))){var saved=NextflowFiles.object(SimpleJson.parse(new String(raw.readAllBytes(),StandardCharsets.UTF_8)));for(Object row:NextflowFiles.list(saved.get("cases")))assertTrue(policy.add(NextflowFiles.text(NextflowFiles.object(row).get("case"))));}
        assertEquals(8,policy.size());
        try(var raw=Objects.requireNonNull(getClass().getResourceAsStream("/org/jlinalg/omics/allcools-posterior/cases.tsv"),"Reproduce exact original-source reference fixtures first");var input=new BufferedReader(new InputStreamReader(raw,StandardCharsets.UTF_8))) {
            assertTrue(input.readLine().startsWith("case\trepresentation\toperation\t"));String line;
            while((line=input.readLine())!=null){String[] f=line.split("\t",-1);assertEquals(11,f.length);cases++;
                var settings=new AllcoolsPosterior.Settings(f[1].equals("numpy")?AllcoolsPosterior.Representation.NUMPY:AllcoolsPosterior.Representation.XARRAY,f[2].equals("posterior-fraction")?AllcoolsPosterior.Operation.POSTERIOR_FRACTION:AllcoolsPosterior.Operation.M_VALUE,Boolean.parseBoolean(f[3]),f[4].equals("null")?null:numeric(f[4]),numeric(f[5]));
                if(policy.remove(f[0])){var error=assertThrows(ArithmeticException.class,()->AllcoolsPosterior.calculate(integers(f[6]),integers(f[7]),settings,()->{}));assertTrue(error.getMessage().contains("M-value normalization mean"));refused++;continue;}
                var r=AllcoolsPosterior.calculate(integers(f[6]),integers(f[7]),settings,()->{});
                double[][] actual={r.posterior(),r.values(),new double[]{r.mean(),r.variance(),r.alpha(),r.beta(),r.priorMean()}};
                for(int column=0;column<3;column++){double[] expected=doubles(f[column+8]);assertEquals(expected.length,actual[column].length);for(int i=0;i<expected.length;i++){compared++;if(!agrees(expected[i],actual[column][i])){failed++;if(failures.size()<20)failures.add(f[0]+" column="+column+" feature="+i+" expected="+expected[i]+" actual="+actual[column][i]);}}}
            }
        }
        assertEquals(384,cases);assertEquals(8,refused);assertTrue(policy.isEmpty());assertTrue(compared>100000,"Full admitted population must be compared");assertEquals(0,failed,"Original-source mismatches: "+failed+" / "+compared+"\n"+String.join("\n",failures));
    }
}
